-- Identidad individual y organización de laboratorio. No reescribe custodia ni actores históricos.
CREATE TABLE staff_account(actor_id VARCHAR(64) PRIMARY KEY,username VARCHAR(64) NOT NULL UNIQUE,email VARCHAR(180) NOT NULL UNIQUE,cargo VARCHAR(120) NOT NULL,unit_code VARCHAR(8),site_id VARCHAR(40),enabled BOOLEAN NOT NULL,security_epoch BIGINT NOT NULL,password_hash VARCHAR(100) NOT NULL,created_ms BIGINT NOT NULL,updated_ms BIGINT NOT NULL,updated_by VARCHAR(64) NOT NULL,FOREIGN KEY(actor_id) REFERENCES core_actor(id),FOREIGN KEY(unit_code,site_id) REFERENCES core_unit_site(unit_code,site_id),FOREIGN KEY(updated_by) REFERENCES core_actor(id));
CREATE TABLE staff_assignment(id VARCHAR(36) PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,role_code VARCHAR(32) NOT NULL,scope_code VARCHAR(24) NOT NULL,unit_code VARCHAR(8),site_id VARCHAR(40),valid_from BIGINT NOT NULL,valid_until BIGINT,revoked_ms BIGINT,granted_by VARCHAR(64) NOT NULL,revoked_by VARCHAR(64),FOREIGN KEY(actor_id) REFERENCES staff_account(actor_id),FOREIGN KEY(granted_by) REFERENCES core_actor(id),FOREIGN KEY(revoked_by) REFERENCES core_actor(id),FOREIGN KEY(unit_code) REFERENCES core_unit(code),FOREIGN KEY(site_id) REFERENCES core_site(id),CHECK(role_code IN ('TI','DISTRIBUCION','DIRECTOR','COORDINADOR','COORDINADOR_REGIONAL','PROFESIONAL','ADMINISTRATIVO')),CHECK(scope_code IN ('INSTITUCION','SEDE','UNIDAD_SEDE')),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE INDEX ix_staff_assignment ON staff_assignment(actor_id,valid_from,revoked_ms);
CREATE TABLE identity_event(seq BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,subject_id VARCHAR(64) NOT NULL,event_code VARCHAR(40) NOT NULL,resource_id VARCHAR(64),at_ms BIGINT NOT NULL,FOREIGN KEY(actor_id) REFERENCES core_actor(id),FOREIGN KEY(subject_id) REFERENCES core_actor(id));
CREATE TABLE org_macrozone(id VARCHAR(40) PRIMARY KEY,label VARCHAR(120) NOT NULL,lab BOOLEAN NOT NULL);
CREATE TABLE org_region(id VARCHAR(40) PRIMARY KEY,label VARCHAR(120) NOT NULL,lab BOOLEAN NOT NULL);
CREATE TABLE org_region_macrozone(id VARCHAR(36) PRIMARY KEY,region_id VARCHAR(40) NOT NULL,macrozone_id VARCHAR(40) NOT NULL,valid_from BIGINT NOT NULL,valid_until BIGINT,FOREIGN KEY(region_id) REFERENCES org_region(id),FOREIGN KEY(macrozone_id) REFERENCES org_macrozone(id),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE TABLE org_site_validity(site_id VARCHAR(40) PRIMARY KEY,valid_from BIGINT NOT NULL,valid_until BIGINT,lab BOOLEAN NOT NULL,FOREIGN KEY(site_id) REFERENCES core_site(id),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE TABLE org_unit_validity(unit_code VARCHAR(8) PRIMARY KEY,valid_from BIGINT NOT NULL,valid_until BIGINT,lab BOOLEAN NOT NULL,FOREIGN KEY(unit_code) REFERENCES core_unit(code),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE TABLE org_coverage(id VARCHAR(36) PRIMARY KEY,region_id VARCHAR(40) NOT NULL,site_id VARCHAR(40) NOT NULL,valid_from BIGINT NOT NULL,valid_until BIGINT,changed_by VARCHAR(64) NOT NULL,changed_ms BIGINT NOT NULL,FOREIGN KEY(region_id) REFERENCES org_region(id),FOREIGN KEY(site_id) REFERENCES core_site(id),FOREIGN KEY(changed_by) REFERENCES core_actor(id),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE TABLE communication_origin(communication_id VARCHAR(36) PRIMARY KEY,origin_code VARCHAR(24) NOT NULL,site_id VARCHAR(40),subject_region VARCHAR(40),FOREIGN KEY(communication_id) REFERENCES communication_registry(comunicacion_id),FOREIGN KEY(site_id) REFERENCES core_site(id),FOREIGN KEY(subject_region) REFERENCES org_region(id),CHECK(origin_code IN ('WEB','REGISTRO_FUNCIONARIO')));
INSERT INTO communication_origin(communication_id,origin_code,site_id) SELECT r.comunicacion_id,CASE WHEN r.source='REGISTRO_FUNCIONARIO' THEN 'REGISTRO_FUNCIONARIO' ELSE 'WEB' END,c.site_id FROM communication_registry r LEFT JOIN core_communication c ON c.id=r.comunicacion_id;
CREATE TABLE distribution_event(destination_id VARCHAR(36) PRIMARY KEY,communication_id VARCHAR(36) NOT NULL,actor_id VARCHAR(64) NOT NULL,origin_site VARCHAR(40),target_unit VARCHAR(8) NOT NULL,target_site VARCHAR(40) NOT NULL,at_ms BIGINT NOT NULL,FOREIGN KEY(destination_id) REFERENCES core_destination(id),FOREIGN KEY(communication_id) REFERENCES communication_registry(comunicacion_id),FOREIGN KEY(actor_id) REFERENCES core_actor(id),FOREIGN KEY(origin_site) REFERENCES core_site(id));

CREATE TABLE identity_guard(id INT PRIMARY KEY);
INSERT INTO identity_guard VALUES(1);
CREATE TABLE staff_profile_history(seq BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,label VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL,cargo VARCHAR(120) NOT NULL,unit_code VARCHAR(8),site_id VARCHAR(40),enabled BOOLEAN NOT NULL,security_epoch BIGINT NOT NULL,changed_by VARCHAR(64) NOT NULL,changed_ms BIGINT NOT NULL,FOREIGN KEY(actor_id) REFERENCES core_actor(id),FOREIGN KEY(changed_by) REFERENCES core_actor(id));
INSERT INTO org_site_validity SELECT id,0,NULL,TRUE FROM core_site;
INSERT INTO org_unit_validity SELECT code,0,NULL,TRUE FROM core_unit;
